fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Assume types is non-empty
    // Find dtype with max precedence from the input slice
    types.into_iter().max_by_key(|dt| dt.precedence).unwrap()
}

fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let array_max = if !array_types.is_empty() {
        Some(find_max_precedence_type(array_types))
    } else {
        None
    };
    let scalar_max = if !scalar_types.is_empty() {
        Some(find_max_precedence_type(scalar_types))
    } else {
        None
    };

    match (array_max, scalar_max) {
        (Some(a), None) => Some(a),
        (None, Some(s)) => Some(s),
        (Some(a), Some(s)) => {
            // If kinds equal, return max from array_types
            if a.kind == s.kind {
                Some(a)
            } else {
                Some(s)
            }
        }
        (None, None) => None, // According to problem, one input should be non-empty, but safe fallback
    }
}

